using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class CountedRelativeGyrationTransportDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Transport forward orbit phases under timed history equivalences.",
        H("Transport forward orbit phases under timed history equivalences"),
        Blocks(
            Paragraph(Text("TimedEquiv A B consists of an equivalence of actual legal two-sided paths and its law for every signed integer translation. It induces the retained primitive-path and orbit-quotient equivalences. basisEquiv expresses the orbit bijection in the existing least-word PathBasis. offsetFin is the canonical target forward offset, offset its ZMod d value, and phaseInteger its nonnegative Fin representative in the integers.")),
            Paragraph(Text("offset_comp keeps the source canonical representative fixed and identifies phases by uniqueness below minimal period, including signed-time Euclidean reduction. Summing and reindexing by basisEquiv gives gyration_comp. gyration_basis_change retains both endpoint terms; gyration_conjugate cancels them only with the same chart. elementary uses the original elementaryHomeomorph and gyration_elementary recovers relativeForwardGyration. timeEquiv A s has gyration equal to the number of actual primitive d-orbits times the signed class of s. General transport laws use all nonzero periods, without imposing divisibility by three or nonemptiness. Agreement only on orbit permutations is insufficient for offset_congr or gyration_congr: both require equality on all actual primitive images.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-orbit-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.orbitEquiv"), H("orbitEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Descend the time-equivariant primitive-path equivalence to the actual orbit quotients at each nonzero period. This transports orbit classes before choosing canonical representatives."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-basis-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.basisEquiv"), H("basisEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Exactly the actual orbit bijection, expressed in the supplier's finite canonical bases. Its target is not chosen independently of the actual map."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-offset-comp"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.offset_comp"), H("offset_comp"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The forward offset of a composite is the first offset plus the second offset at the transported canonical basis path. Phase uniqueness controls the sum modulo the period."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-timed-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.TimedEquiv"), H("TimedEquiv"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A genuine equivalence of the two actual legal-history carriers, with the literal integer-time law. This packages equivariance, never a gyration identity.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-refl"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.refl"), H("refl"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The identity path equivalence preserves every integer translation. It is the identity object for the transport and gyration laws.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-comp"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.comp"), H("comp"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Compose the actual path equivalences and their signed-time laws in traversal order. The intermediate counted graph is retained.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-symm"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.symm"), H("symm"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Invert the path equivalence and derive its signed-time law from bijectivity. This gives reverse transport on the same histories.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-ext"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.ext"), H("ext"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Pointwise equality of the underlying path maps determines a TimedEquiv. The time-law proof contributes no additional choice.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-semiconj"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.semiconj"), H("semiconj"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The integer-time law at one gives semiconjugacy of the actual forward shifts. This connects time-equivariant maps to the existing periodic-point API.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-minimal-period"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.minimalPeriod"), H("minimalPeriod"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A time-equivariant equivalence preserves the least period of every path. Applying the forward and inverse maps gives equality rather than only divisibility.")))),
            
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-primitive-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.primitiveEquiv"), H("primitiveEquiv"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Restrict to paths whose least period is exactly d. This is the primitive stratum used in the orbit and phase construction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-primitive-equiv-congr"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.primitiveEquiv_congr"), H("primitiveEquiv_congr"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Agreement on the actual primitive histories gives equality of their primitive images, including the original target history, by subtype extensionality.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-same-orbit-iff"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.sameOrbit_iff"), H("sameOrbit_iff"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Two primitive paths lie in the same shift orbit exactly when their images do. The forward and inverse time laws justify descent to orbit quotients.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-basis-equiv-apply"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.basisEquiv_apply"), H("basisEquiv_apply"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The induced basis map chooses the existing canonical representative of the transported primitive path. It does not choose a new orbit ordering.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-basis-equiv-comp"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.basisEquiv_comp"), H("basisEquiv_comp"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Canonical basis transport respects composition. This is the reindexing identity used when summing composite offsets.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-offset-fin"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.offsetFin"), H("offsetFin"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Choose the unique forward offset below d from the target canonical representative to the actual image path. Primitivity and nonzero d control uniqueness.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-offset"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.offset"), H("offset"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Read the canonical forward offset in ZMod d. Reduction retains the phase even when the induced orbit permutation is unchanged.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-offset-congr"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.offset_congr"), H("offset_congr"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Both offsets use the identical canonical SOURCE basis representative. Equality of the actual primitive target images identifies their canonical forward offsets; equality of orbit permutations alone would not suffice.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-phase-integer"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.phaseInteger"), H("phaseInteger"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Interpret the canonical Fin offset as a nonnegative integer. This is the signed-time representative used in the literal history equation.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-phase-equation"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.phase_equation"), H("phase_equation"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The actual image path is the transported canonical representative translated by its forward phase. This relates the finite offset to the full integer-indexed history.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-fin-equiv-time-index"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.finEquiv_timeIndex"), H("finEquiv_timeIndex"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Reduce an arbitrary SIGNED integer, using Euclidean blockAddress, not a homomorphism from all rationals or an unstated orientation convention.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration"), H("gyration"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Sum the forward offsets over the existing finite canonical primitive basis. Empty primitive strata contribute the empty sum.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-congr"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_congr"), H("gyration_congr"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The original forward-offset sum depends only on the map on actual primitive d histories. The finite canonical source basis is the same in both sums.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-comp"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_comp"), H("gyration_comp"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Sum offset_comp and reindex by the transported basis equivalence. The resulting gyration is additive under composition for every nonzero period.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-refl"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_refl"), H("gyration_refl"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The identity map has zero forward offset on each canonical primitive path, so its total gyration is zero.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-symm"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_symm"), H("gyration_symm"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Apply additivity to a map and its inverse. The inverse gyration is the additive negative of the original value.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-basis-change"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_basis_change"), H("gyration_basis_change"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Basis changes telescope, including both endpoint terms. For a loop the same actual chart is used at both ends, so its two terms cancel.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-conjugate"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_conjugate"), H("gyration_conjugate"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The two contributions of the same change of path coordinates cancel around a loop. This proves conjugacy invariance of the total gyration.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-elementary"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.elementary"), H("elementary"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Finite automorphisms may rotate an orbit: no relabeling-zero rule occurs.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-elementary"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_elementary"), H("gyration_elementary"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For the existing elementary RS-to-SR homeomorphism, the transport sum is exactly relativeForwardGyration. Both use the original ranked primitive paths.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-time-equiv"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.timeEquiv"), H("timeEquiv"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Translate every history by the signed integer s. Translation is a time-equivariant automorphism of the same counted graph.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-basis-equiv-time"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.basisEquiv_time"), H("basisEquiv_time"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Time translation preserves each primitive orbit and hence its canonical basis representative. Its nontrivial contribution lies in the phase.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-offset-time"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.offset_time"), H("offset_time"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("On every canonical primitive d-path, signed translation by s has forward offset equal to s modulo d.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-countedrelativegyrationtransport-gyration-time"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/CountedRelativeGyrationTransport.gyration_time"), H("gyration_time"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every primitive orbit contributes the same signed offset s. Summing gives the actual primitive-orbit cardinality multiplied by s in ZMod d.")))))));
}
